export const handler = async (input) => {
  // 发票内容唯一使用数据准备阶段由 items[*].goodsName 汇总出的单据级 goodsName。
  const goodsName = String(input.goodsName ?? '');
  // 用 JSON.stringify 注入，避免商品名称中的反引号或 ${...} 破坏模板字符串。
  const goodsNameForPrompt = JSON.stringify(goodsName);

  const optimizedPrompt = `# 角色
你是企业费用制度合规审核专家，负责判断业务招待费发票【项目名称】是否命中公司制度的禁止报销清单。

# 审核范围
只根据下面给出的发票项目名称判断，不要根据金额、销货方、发票类型或关键词的单独出现做推断。
公司制度明确禁止报销的项目为：
1. 黄金（作为贵金属、金条、金币、黄金制品等）；
2. 珠宝；
3. 首饰；
4. 茅台；
5. 五粮液；
6. 礼品卡；
7. 充值卡（包括明确属于预付/储值/充值卡的项目）。

# 语义判断要求（非常重要）
这是语义审核，不是字符串包含判断：
- “黄金针菇”是蔬菜，不是黄金，必须通过；
- “黄金饰品”“黄金手链”“黄金摆件”属于黄金/首饰，必须不通过；
- “珠宝首饰”“钻石珠宝”等明确属于珠宝或首饰，必须不通过；
- “茅台酒”“五粮液白酒”明确属于对应品牌，必须不通过；
- 仅因出现“黄金”二字但实际是食品、植物、地名或其他普通商品（例如黄金针菇、黄金果），不能判为不通过；
- 仅有“礼品”二字不等于礼品卡；只有明确是礼品卡、充值卡或预付/储值卡等卡类/资金预存项目时才不通过；
- 项目名称含义不清、无法确认命中禁止清单时，默认通过；
- 多个项目名称中只要有一个明确命中禁止清单，就判定不通过。

# 输出要求
必须只返回一个标准 JSON 对象，不得返回 Markdown、解释、推理过程或其他文字：
{
  "passed": true 或 false,
  "violationType": "none"、"prohibited_item" 或 "recharge_card"
}

字段约束：
- passed=true 时，violationType 必须为 "none"；
- 命中黄金、珠宝、首饰、茅台、五粮液时，violationType 返回 "prohibited_item"；
- 命中礼品卡、充值卡或明确的预付/储值卡时，violationType 返回 "recharge_card"。

# 待审核的发票项目名称（JSON 字符串）
${goodsNameForPrompt}`;

  return {
    prompt: optimizedPrompt,
    context: input.context || {}
  };
};

import http from 'http';

export const handler = async (input) => {
  try {
    const context = input && input.context ? input.context : {};
    if (!context.llmGatewayUrl) {
      throw new Error('llmGatewayUrl not injected in context; configure NODE_GATEWAY_URL in .env');
    }
    const LOCAL_LLM_URL = context.llmGatewayUrl;
    const prompt = input.prompt || context.prompt || (input.prev && input.prev.prompt) || '';

    if (!prompt) {
      throw new Error('missing prompt from previous component output');
    }

    const payload = {
      prompt
    };

    if (input.systemPrompt || context.systemPrompt) {
      payload.systemPrompt = input.systemPrompt || context.systemPrompt;
    }

    if (typeof input.temperature === 'number' || typeof context.temperature === 'number') {
      payload.temperature = typeof input.temperature === 'number' ? input.temperature : context.temperature;
    }

    if (input.context && input.context.runId) { payload.runId = input.context.runId; }
    if (input.context && input.context.receiptCode) { payload.receiptCode = input.context.receiptCode; }
    if (input.context && input.context.invoiceKey) { payload.invoiceKey = input.context.invoiceKey; }
    const response = await http.post(LOCAL_LLM_URL, payload);

    if (!response || response.status < 200 || response.status >= 300) {
      throw new Error('local llm service failed at ' + LOCAL_LLM_URL + ': ' + (response && response.status ? response.status : 'unknown'));
    }

    const result = typeof response.data === 'string' ? JSON.parse(response.data) : (response.data || {});

    return {
      llm_status: result.llmStatus || 'error',
      llm_result: result.llmResult || null,
      raw_content: result.rawContent || null,
      error_message: result.errorMessage || null
    };
  } catch (error) {
    return {
      llm_status: 'error',
      llm_result: null,
      raw_content: null,
      error_message: error && error.message ? error.message : String(error)
    };
  }
};

export const handler = async (input) => {
  const context = input.context || {};
  const needCheck = input.needLlmAddressCheck ?? context.needLlmAddressCheck ?? false;

  // 如果不需要 LLM 检查，直接返回通过
  if (!needCheck) {
    return {
      prompt: '无需检查，直接返回通过',
      context: input.context || {},
      skipLlm: true
    };
  }

  const salerName = input.salerName ?? context.salerName ?? '';
  const salerAddress = input.salerCompanyInfo?.address ?? context.salerCompanyInfo?.address ?? '';
  const allSalerAddresses = input.allSalerAddresses ?? context.allSalerAddresses ?? [];

  const optimizedPrompt = `# Role
你是一位企业税务风险审计专家，专门识别虚开发票的高风险特征。

# Task
请根据以下销货方企业注册地址信息，判断是否存在虚开发票风险。

# 人工规则（需 LLM 泛化判断）
1. 多家开票企业注册地点相似程度达90%以上（可能是同一地址的不同表述）
2. 企业注册地点为居民楼、小区、农村自建房等非商业经营场所

# 待审查数据
- 当前销货方名称：${salerName}
- 当前销货方注册地址：${salerAddress}
- 本核销单所有销货方注册地址列表：${JSON.stringify(allSalerAddresses)}

# 判定规则
- 如果当前地址与列表中其他地址相似度≥90%（如仅门牌号不同、表述略有差异），返回 passed=false
- 如果注册地址明显为居民楼、小区、农村等非商业场所，返回 passed=false
- 否则返回 passed=true
- 存在歧义时默认 passed=true

# 输出格式
你必须【仅仅且直接】返回一个标准的 JSON 对象：
{
  "passed": 判定结果（布尔类型 true 或 false）,
  "riskReason": 风险原因说明（字符串，passed=false 时填写具体风险点）
}`;

  return {
    prompt: optimizedPrompt,
    context: input.context || {}
  };
};

